fun (t : ℝ) =>
  if t < DominantFiveBody.Coorbital.h then DominantFiveBody.Coorbital.kernelF t / (DominantFiveBody.Coorbital.h - t)
  else if t = DominantFiveBody.Coorbital.h then (0 : ℝ) else DominantFiveBody.Coorbital.kernelF t / (Real.pi - t)

fun (mass theta : DominantFiveBody.Satellite → ℝ) (i j : DominantFiveBody.Satellite) =>
  if i < j then mass i * mass j * DominantFiveBody.Coorbital.kappa (theta j - theta i)
  else if j < i then mass j * mass i * DominantFiveBody.Coorbital.kappa (theta i - theta j) else (0 : ℝ)
